70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Dedicated audit logger. On a successful create an audit line carrying the new owner's id,
74	     * {@code customerCode}, {@code registrationDate} and {@code membershipLevel} is emitted to the
75	     * logger named {@code AUDIT}.
76	     */
77	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
78	
79	    /**
80	     * Syntactic check for an email address: a non-empty local part, an {@code @}, and a domain with
81	     * at least one dot and no whitespace on either side.
82	     */
83	    private static final Pattern EMAIL_PATTERN =
84	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
85	
86	    /**
87	     * Common street-type abbreviations expanded during address normalization. Keys are the
88	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
89	     * expanded form.
90	     */
91	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
92	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
93	
94	    /**
95	     * Required national-number length per E.164 country code (the digits that follow the country
96	     * code). {@code '+61'} (Australia) requires 9 national digits; {@code '+1'} (NANP) requires 10.
97	     * A country code that is not listed here is not length-checked, keeping other numbers accepted.
98	     */
99	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH =
100	        Map.of("1", 10, "61", 9);
101	
102	    /**
103	     * Inclusive 4-digit postcode range allowed for each known region, keyed by the region an owner's
104	     * city derives to (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD): NSW 2000-2099, VIC
105	     * 3000-3099, QLD 4000-4099. A city that derives to no known region ({@code "UNKNOWN"}) is not in
106	     * this table and accepts any 4-digit postcode.
107	     */
108	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
109	        "NSW", new int[] {2000, 2099},
110	        "VIC", new int[] {3000, 3099},
111	        "QLD", new int[] {4000, 4099});
112	
113	    /**
114	     * The maximum number of owners a single city may contain. A create request for a city that
115	     * already holds this many owners is rejected with a 409 response.
116	     */
117	    private static final int MAX_OWNERS_PER_CITY = 50;
118	
119	    /**
120	     * The maximum number of owners that may be registered in a single day. A create request made
121	     * once this many owners already carry today's {@code registrationDate} is rejected with a 429
122	     * response.
123	     */
124	    private static final int MAX_OWNERS_PER_DAY = 100;
125	
126	    /**
127	     * The number of owners that must already carry a day's {@code registrationDate} before a create
128	     * for that day is flagged as a bulk signup. Once more than this many owners already exist for the
129	     * day, the new owner is created with {@code bulkSignupWarning} set to {@code true}.
130	     */
131	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
