151	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
152	    @Override
153	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
154	        Collection<Owner> owners;
155	        if (lastName != null) {
156	            owners = this.clinicService.findOwnerByLastName(lastName);
157	        } else {
158	            owners = this.clinicService.findAllOwners();
159	        }
160	        if (owners.isEmpty()) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
164	    }
