176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Override
178	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
179	        normalizeAddress(ownerFieldsDto);
180	        validateRequiredFields(ownerFieldsDto);
181	        normalizeTelephone(ownerFieldsDto);
182	        normalizeEmail(ownerFieldsDto);
183	        validatePostcode(ownerFieldsDto);
184	        rejectDuplicateIdentity(ownerFieldsDto, resolveHouseholdId(ownerFieldsDto));
185	        rejectCityAtCapacity(ownerFieldsDto);
186	        resolveRegistrationDate(ownerFieldsDto);
187	        rejectDailyLimitReached(ownerFieldsDto.getRegistrationDate());
188	        HttpHeaders headers = new HttpHeaders();
189	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
190	        assignCustomerCode(owner);
191	        assignMembershipNumber(owner);
192	        assignNamesakeCount(owner);
193	        assignMembershipLevel(owner);
194	        assignBulkSignupWarning(owner);
195	        assignPossibleDuplicate(owner);
196	        assignHousehold(owner, ownerFieldsDto);
197	        assignHouseholdMembership(owner);
198	        this.clinicService.saveOwner(owner);
199	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
200	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
201	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
202	        headers.setLocation(UriComponentsBuilder.newInstance()
203	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
204	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
205	    }
