214	        currentOwner.setAddress(ownerFieldsDto.getAddress());
215	        currentOwner.setCity(ownerFieldsDto.getCity());
216	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
217	        currentOwner.setLastName(ownerFieldsDto.getLastName());
218	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
219	        normalizeEmail(ownerFieldsDto);
220	        currentOwner.setEmail(ownerFieldsDto.getEmail());
221	        this.clinicService.saveOwner(currentOwner);
222	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
