302	    /**
303	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
304	     * {@code telephone} is missing or blank (including whitespace-only values that Bean Validation
305	     * does not catch). The names of all offending fields are collected so the caller receives a
306	     * 400 response whose {@code errors} array lists each one.
307	     */
308	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
309	        List<String> missingFields = new ArrayList<>();
310	        if (isBlank(ownerFieldsDto.getFirstName())) {
311	            missingFields.add("firstName");
312	        }
313	        if (isBlank(ownerFieldsDto.getLastName())) {
314	            missingFields.add("lastName");
315	        }
316	        if (isBlank(ownerFieldsDto.getAddress())) {
317	            missingFields.add("address");
318	        }
319	        if (isBlank(ownerFieldsDto.getCity())) {
320	            missingFields.add("city");
321	        }
322	        if (isBlank(ownerFieldsDto.getTelephone())) {
323	            missingFields.add("telephone");
324	        }
325	        if (!missingFields.isEmpty()) {
326	            throw new InvalidOwnerFieldsException(missingFields);
327	        }
328	    }
329	
330	    private static boolean isBlank(String value) {
331	        return value == null || value.trim().isEmpty();
332	    }
333	
334	    /**
335	     * Normalizes an owner's {@code address} on create and writes the canonical form back onto the
336	     * request so it is what gets validated, compared, stored and returned. The value is trimmed,
337	     * runs of internal whitespace are collapsed to a single space, the result is upper-cased and
338	     * common street-type abbreviations are expanded as whole tokens ({@code ST}->{@code STREET},
339	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). Running before the required-field check
340	     * means an address that is blank after normalization is rejected like a missing one.
341	     */
342	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
343	        ownerFieldsDto.setAddress(canonicalAddress(ownerFieldsDto.getAddress()));
344	    }
345	
346	    /**
347	     * Returns the canonical form of an address: trimmed, internal whitespace runs collapsed to a
348	     * single space, upper-cased, with common street-type abbreviations expanded as whole tokens. A
349	     * {@code null} value returns {@code null}. The transform is idempotent, so an already-canonical
350	     * address is returned unchanged, making it safe to apply to stored values during comparison.
351	     */
352	    private static String canonicalAddress(String address) {
353	        if (address == null) {
354	            return null;
355	        }
356	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
357	        if (collapsed.isEmpty()) {
358	            return "";
359	        }
360	        String[] tokens = collapsed.split(" ");
361	        StringBuilder sb = new StringBuilder(collapsed.length());
362	        for (int i = 0; i < tokens.length; i++) {
363	            if (i > 0) {
364	                sb.append(' ');
365	            }
366	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
367	        }
368	        return sb.toString();
369	    }
370	
371	    /**
372	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
373	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
374	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
375	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}, and when the
376	     * country code is one whose national-number length is known ({@code '+61'} => 9 national digits,
377	     * {@code '+1'} => 10) the national number must have exactly that many digits. The E.164 string is
378	     * written back onto the request so it is what gets stored and returned. Any value that cannot
379	     * form a valid E.164 number is rejected with a 400 response whose {@code errors} array names
380	     * {@code telephone}.
381	     */
382	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
383	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
384	    }
385	
386	    /**
387	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
388	     * (400) naming {@code telephone} when it cannot form a valid number.
389	     */
390	    private static String toE164(String telephone) {
391	        if (telephone == null) {
392	            throw new InvalidOwnerFieldsException(List.of("telephone"));
393	        }
394	        boolean hasCountryCode = telephone.trim().startsWith("+");
395	        String digits = telephone.replaceAll("\\D", "");
396	        String countryCode;
397	        String national;
398	        if (hasCountryCode) {
399	            countryCode = matchCountryCode(digits);
400	            national = digits;
401	        } else {
402	            countryCode = "61";
403	            if (digits.startsWith("0")) {
404	                digits = digits.substring(1);
405	            }
406	            national = "61" + digits;
407	        }
408	        if (!national.matches("[0-9]{8,15}")) {
409	            throw new InvalidOwnerFieldsException(List.of("telephone"));
410	        }
411	        if (countryCode != null) {
412	            Integer requiredLength = COUNTRY_NATIONAL_LENGTH.get(countryCode);
413	            if (requiredLength != null
414	                && national.length() - countryCode.length() != requiredLength) {
415	                throw new InvalidOwnerFieldsException(List.of("telephone"));
416	            }
417	        }
418	        return "+" + national;
419	    }
420	
421	    /**
422	     * Returns the longest known E.164 country code (a key of {@link #COUNTRY_NATIONAL_LENGTH}) that
423	     * the given country-code-prefixed digit string starts with, or {@code null} when none is known so
424	     * the number is not length-checked against a country.
425	     */
426	    private static String matchCountryCode(String digits) {
427	        return COUNTRY_NATIONAL_LENGTH.keySet().stream()
428	            .filter(digits::startsWith)
429	            .max(Comparator.comparingInt(String::length))
430	            .orElse(null);
431	    }
432	
433	    /**
434	     * Rejects creating an owner whose derived {@code identityKey} already, in its entirety, belongs
435	     * to another owner. The key is {@code normalizedTelephone + '|' + (email or empty) + '|' +
436	     * (householdId or empty)}, so it folds the former separate telephone, email and household
437	     * duplicate checks into one: only an exact full-key match is a duplicate. In particular two
438	     * members of the same household (same {@code householdId}) with different telephones have
439	     * different keys and are both allowed. The incoming telephone and email have already been
440	     * normalized by {@link #normalizeTelephone} and {@link #normalizeEmail}, and the household id has
441	     * been resolved by {@link #resolveHouseholdId}; each existing owner's key is derived the same way
442	     * before comparison. A match results in a 409 response naming {@code identityKey}.
443	     */
444	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto, String householdId) {
445	        String identityKey = identityKey(ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
446	        for (Owner existing : this.clinicService.findAllOwners()) {
447	            if (identityKey.equals(existingIdentityKey(existing))) {
448	                throw new DuplicateOwnerIdentityException(identityKey);
449	            }
450	        }
451	    }
452	
453	    /**
454	     * Builds an {@code identityKey} from its three parts: {@code telephone + '|' + email + '|' +
455	     * householdId}, with a {@code null} part contributing the empty string. The telephone and email
456	     * are expected to already be in their normalized (E.164, lower-cased) forms.
457	     */
458	    private static String identityKey(String telephone, String email, String householdId) {
459	        return orEmpty(telephone) + "|" + orEmpty(email) + "|" + orEmpty(householdId);
460	    }
461	
462	    /**
463	     * Derives an already-stored owner's {@code identityKey} for duplicate comparison: the stored
464	     * telephone is converted to E.164 form (or the empty string when it cannot form a valid number),
465	     * the stored email is lower-cased, and the stored household id is used as-is.
466	     */
467	    private static String existingIdentityKey(Owner existing) {
468	        String telephone = orEmpty(normalizeExisting(existing.getTelephone()));
469	        String email = existing.getEmail() == null ? "" : existing.getEmail().toLowerCase(Locale.ROOT);
470	        return identityKey(telephone, email, existing.getHouseholdId());
471	    }
472	
473	    private static String orEmpty(String value) {
474	        return value == null ? "" : value;
475	    }
476	
477	    /**
478	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, or {@code null}
479	     * when the stored value cannot form a valid E.164 number (so it never matches an incoming one).
480	     */
481	    private static String normalizeExisting(String telephone) {
482	        try {
483	            return toE164(telephone);
484	        } catch (InvalidOwnerFieldsException ex) {
485	            return null;
486	        }
487	    }
488	
489	    /**
490	     * Rejects creating an owner in a city that has reached capacity: a city that already contains
491	     * {@value #MAX_OWNERS_PER_CITY} or more owners cannot take another one. Existing owners are
492	     * counted with a case-insensitive match on {@code city}, the same way {@link #assignCustomerCode}
493	     * groups a city. A city at or over the limit results in a 409 response naming {@code city}.
494	     */
495	    private void rejectCityAtCapacity(OwnerFieldsDto ownerFieldsDto) {
496	        String city = ownerFieldsDto.getCity();
497	        int count = 0;
498	        for (Owner existing : this.clinicService.findAllOwners()) {
499	            if (city.equalsIgnoreCase(existing.getCity())) {
500	                count++;
501	            }
502	        }
503	        if (count >= MAX_OWNERS_PER_CITY) {
504	            throw new OwnerCityAtCapacityException(city);
505	        }
506	    }
507	
508	    /**
509	     * Rejects creating an owner once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the
510	     * given adjusted business-day {@code registrationDate}, counted by an exact match. The date has
511	     * already been resolved and rolled forward off a weekend by {@link #resolveRegistrationDate}, so
512	     * the limit is enforced per business day. A day at or over the limit results in a 429 response.
513	     */
514	    private void rejectDailyLimitReached(LocalDate registrationDate) {
515	        int count = 0;
516	        for (Owner existing : this.clinicService.findAllOwners()) {
517	            if (registrationDate.equals(existing.getRegistrationDate())) {
518	                count++;
519	            }
520	        }
521	        if (count >= MAX_OWNERS_PER_DAY) {
522	            throw new DailyOwnerLimitReachedException(registrationDate);
523	        }
524	    }
525	
526	    /**
527	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and
528	     * trailing whitespace is trimmed, internal runs of whitespace are collapsed to a single space and
529	     * the result is lower-cased. A {@code null} value normalizes to the empty string.
530	     */
531	    private static String normalizeForComparison(String value) {
532	        if (value == null) {
533	            return "";
534	        }
535	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
536	    }
537	
538	    /**
539	     * Normalizes an owner's optional {@code email}. The field may be omitted entirely, but when a
540	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
541	     * written back onto the request so that is what gets stored and returned. A present but invalid
542	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
543	     */
544	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
545	        String email = ownerFieldsDto.getEmail();
546	        if (email == null) {
547	            return;
548	        }
549	        String trimmed = email.trim();
550	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
551	            throw new InvalidOwnerFieldsException(List.of("email"));
552	        }
553	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
554	    }
555	
556	    /**
557	     * Validates an owner's optional {@code postcode} on create. The field may be omitted entirely
558	     * (so an owner created without a postcode stays accepted), but when a value is present it must be
559	     * exactly 4 digits and valid for the region the owner's {@code city} derives to: NSW 2000-2099,
560	     * VIC 3000-3099, QLD 4000-4099. A city with no known region accepts any 4-digit postcode. A
561	     * present postcode that is malformed or out of range for the city's region is rejected with a 400
562	     * response whose {@code errors} array names {@code postcode}. A valid value is left on the request
563	     * as-is so it is stored and returned.
564	     */
565	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
566	        String postcode = ownerFieldsDto.getPostcode();
567	        if (postcode == null) {
568	            return;
569	        }
570	        if (!postcode.matches("[0-9]{4}")) {
571	            throw new InvalidOwnerFieldsException(List.of("postcode"));
572	        }
573	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.derive(ownerFieldsDto.getCity()));
574	        if (range != null) {
575	            int value = Integer.parseInt(postcode);
576	            if (value < range[0] || value > range[1]) {
577	                throw new InvalidOwnerFieldsException(List.of("postcode"));
578	            }
579	        }
580	    }
581	
582	    /**
583	     * Resolves an owner's effective {@code registrationDate} on create and rolls it onto a business
584	     * day. When the caller supplies no value it defaults to the server's current date; a value
585	     * provided in the request is kept. A supplied value later than the server's current date is
586	     * rejected with a 400 response whose {@code errors} array names {@code registrationDate}. The
587	     * effective date, whether supplied or defaulted, must fall on a business day: a Saturday or
588	     * Sunday is rolled forward to the following Monday. The adjusted date is written back onto the
589	     * request so it is what gets stored and returned (in ISO {@code YYYY-MM-DD} format) and what
590	     * every value derived from the registration date is based on.
591	     */
592	    private void resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
593	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
594	        if (effective == null) {
595	            effective = LocalDate.now();
596	        }
597	        else if (effective.isAfter(LocalDate.now())) {
598	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
599	        }
600	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
601	    }
602	
603	    /**
604	     * Rolls a date forward onto a business day: a Saturday or Sunday is advanced to the following
605	     * Monday; a weekday is returned unchanged.
606	     */
607	    private static LocalDate toBusinessDay(LocalDate date) {
608	        return switch (date.getDayOfWeek()) {
609	            case SATURDAY -> date.plusDays(2);
610	            case SUNDAY -> date.plusDays(1);
611	            default -> date;
612	        };
613	    }
614	
615	    /**
616	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<REGION>-<HASH8>'} where
617	     * {@code REGION} is the region the owner's identity derives to from its postcode (falling back to
618	     * the city table when the postcode is absent or in no known range) and {@code HASH8} is the first
619	     * eight upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
620	     * with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The telephone has already been normalized to
621	     * E.164 form by {@link #normalizeTelephone}. There is no per-city sequence: the identity is a
622	     * pure function of region, telephone and last name.
623	     */
624	    private void assignCustomerCode(Owner owner) {
625	        String region = OwnerLocality.derive(owner.getCity(), owner.getPostcode());
626	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName(), 8);
627	        owner.setCustomerCode(region + "-" + hash8);
628	    }
629	
630	    /**
631	     * Assigns the owner's {@code membershipNumber} on create, formatted
632	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
633	     * {@code registrationDate} year (e.g. {@code 'NSW-1A2B3C4D-M26'}). Assigned after
634	     * {@link #assignCustomerCode} and once {@code registrationDate} has been defaulted, so both
635	     * inputs are present.
636	     */
637	    private void assignMembershipNumber(Owner owner) {
638	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
639	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
640	    }
641	
642	    /**
643	     * Assigns the new owner's {@code namesakeCount} on create: the number of owners that already
644	     * exist sharing the same {@code firstName} and {@code lastName}, compared case-insensitively.
645	     * Computed before the new owner is persisted, so it counts only the pre-existing owners.
646	     */
647	    private void assignNamesakeCount(Owner owner) {
648	        String firstName = owner.getFirstName();
649	        String lastName = owner.getLastName();
650	        int count = 0;
651	        for (Owner existing : this.clinicService.findAllOwners()) {
652	            if (firstName.equalsIgnoreCase(existing.getFirstName())
653	                && lastName.equalsIgnoreCase(existing.getLastName())) {
654	                count++;
655	            }
656	        }
657	        owner.setNamesakeCount(count);
658	    }
659	
660	    /**
661	     * Assigns the new owner's {@code membershipLevel} on create: a number from 1 to 3 starting at
662	     * 1, plus 1 when an email is present, plus 1 when {@code namesakeCount} is 0, capped at 3.
663	     * Level 4 is reserved for tenure. Runs after {@link #assignNamesakeCount} so that count is
664	     * settled.
665	     */
666	    private void assignMembershipLevel(Owner owner) {
667	        int level = 1;
668	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
669	            level++;
670	        }
671	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
672	            level++;
673	        }
674	        owner.setMembershipLevel(Math.min(level, 3));
675	    }
676	
677	    /**
678	     * Assigns the new owner's {@code bulkSignupWarning} on create: {@code true} when more than
679	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the new owner's adjusted
680	     * business-day {@code registrationDate}, otherwise {@code false}. Counted the same way as the
681	     * daily-limit rule and computed before the new owner is persisted, so it counts only the
682	     * pre-existing owners for that day.
683	     */
684	    private void assignBulkSignupWarning(Owner owner) {
685	        LocalDate registrationDate = owner.getRegistrationDate();
686	        int count = 0;
687	        for (Owner existing : this.clinicService.findAllOwners()) {
688	            if (registrationDate.equals(existing.getRegistrationDate())) {
689	                count++;
690	            }
691	        }
692	        owner.setBulkSignupWarning(count > BULK_SIGNUP_WARNING_THRESHOLD);
693	    }
694	
695	    /**
696	     * Assigns the new owner's {@code possibleDuplicate} / {@code possibleDuplicateOf} on create. The
697	     * owner has already cleared the hard-duplicate {@code identityKey} check, so it is not a hard
698	     * duplicate. It is flagged as a possible duplicate when an existing owner shares its
699	     * {@code lastName} (compared case-insensitively) and its {@code postcode} (a present, exact
700	     * match) while carrying a different {@code telephone}. When such an owner exists,
701	     * {@code possibleDuplicate} is set to {@code true} and {@code possibleDuplicateOf} to that owner's
702	     * id (the lowest id when several match); otherwise {@code possibleDuplicate} is {@code false} and
703	     * {@code possibleDuplicateOf} is left {@code null}. Computed before the new owner is persisted, so
704	     * it considers only the pre-existing owners.
705	     */
706	    private void assignPossibleDuplicate(Owner owner) {
707	        String lastName = owner.getLastName();
708	        String postcode = owner.getPostcode();
709	        String telephone = owner.getTelephone();
710	        Integer matchId = null;
711	        if (postcode != null) {
712	            for (Owner existing : this.clinicService.findAllOwners()) {
713	                if (lastName.equalsIgnoreCase(existing.getLastName())
714	                    && postcode.equals(existing.getPostcode())
715	                    && !postcode.isBlank()
716	                    && !java.util.Objects.equals(telephone, existing.getTelephone())
717	                    && existing.getId() != null
718	                    && (matchId == null || existing.getId() < matchId)) {
719	                    matchId = existing.getId();
720	                }
721	            }
722	        }
723	        owner.setPossibleDuplicate(matchId != null);
724	        owner.setPossibleDuplicateOf(matchId);
725	    }
726	
727	    /**
728	     * Assigns the new owner's {@code householdId} when the request opts in with
729	     * {@code sharesHousehold} set to {@code true} and at least one existing owner already shares the
730	     * same last name and address (compared case-insensitively with runs of whitespace collapsed, the
731	     * same way {@link #householdMembers} matches). The household's members and the new owner
732	     * all end up carrying one stable shared identifier: if any existing member already has a
733	     * {@code householdId} it is reused, otherwise a new one is derived from the normalized last name
734	     * and address. Any existing member that is missing the identifier is updated so the whole
735	     * household stays consistent. When the flag is absent, or set but no matching owner exists, no
736	     * identifier is assigned.
737	     */
738	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
739	        String householdId = resolveHouseholdId(ownerFieldsDto);
740	        if (householdId == null) {
741	            return;
742	        }
743	        owner.setHouseholdId(householdId);
744	        String lastName = normalizeForComparison(owner.getLastName());
745	        String address = canonicalAddress(owner.getAddress());
746	        for (Owner member : householdMembers(lastName, address)) {
747	            if (!householdId.equals(member.getHouseholdId())) {
748	                member.setHouseholdId(householdId);
749	                this.clinicService.saveOwner(member);
750	            }
751	        }
752	    }
753	
754	    /**
755	     * Resolves, without any mutation, the {@code householdId} a new owner would be assigned, so it
756	     * can feed both the {@code identityKey} duplicate check and the actual {@link #assignHousehold}
757	     * assignment. Returns {@code null} unless the request opts in with {@code sharesHousehold} set to
758	     * {@code true} and at least one existing owner already shares the same normalized last name and
759	     * address; in that case the household's existing stable identifier is reused, or a new one is
760	     * derived from the normalized last name and address when none of the members carries one yet.
761	     */
762	    private String resolveHouseholdId(OwnerFieldsDto ownerFieldsDto) {
763	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
764	            return null;
765	        }
766	        String lastName = normalizeForComparison(ownerFieldsDto.getLastName());
767	        String address = canonicalAddress(ownerFieldsDto.getAddress());
768	        List<Owner> members = householdMembers(lastName, address);
769	        if (members.isEmpty()) {
770	            return null;
771	        }
772	        return members.stream()
773	            .map(Owner::getHouseholdId)
774	            .filter(id -> id != null && !id.isBlank())
775	            .findFirst()
776	            .orElseGet(() -> newHouseholdId(lastName, address));
777	    }
778	
779	    /**
780	     * Returns every existing owner sharing the given normalized last name and address (compared
781	     * case-insensitively with runs of whitespace collapsed), the members of a household.
782	     */
783	    private List<Owner> householdMembers(String normalizedLastName, String normalizedAddress) {
784	        List<Owner> members = new ArrayList<>();
785	        for (Owner existing : this.clinicService.findAllOwners()) {
786	            if (normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
787	                && normalizedAddress.equals(canonicalAddress(existing.getAddress()))) {
788	                members.add(existing);
789	            }
790	        }
791	        return members;
792	    }
793	
794	    /**
795	     * Assigns the new owner's {@code householdMemberCount} on create: the number of owners sharing
796	     * the new owner's {@code householdId} once this create is applied — that is, the new owner plus
797	     * every existing owner already carrying the same identifier. Runs after {@link #assignHousehold}
798	     * so the identifier is settled. Left {@code null} when the owner belongs to no household.
799	     */
800	    private void assignHouseholdMembership(Owner owner) {
801	        String householdId = owner.getHouseholdId();
802	        if (householdId == null || householdId.isBlank()) {
803	            owner.setHouseholdMemberCount(null);
804	            return;
805	        }
806	        int count = 1;
807	        for (Owner existing : this.clinicService.findAllOwners()) {
808	            if (householdId.equals(existing.getHouseholdId())) {
809	                count++;
810	            }
811	        }
812	        owner.setHouseholdMemberCount(count);
813	    }
814	
815	    /**
816	     * Derives a stable household identifier from the normalized last name and address: the first
817	     * twelve upper-case hex characters of the SHA-256 digest of {@code "<lastName>|<address>"}. Two
818	     * owners in the same household therefore derive the same value regardless of creation order.
819	     */
820	    private static String newHouseholdId(String normalizedLastName, String normalizedAddress) {
821	        return shaHexUpper(normalizedLastName + "|" + normalizedAddress, 12);
822	    }
823	
824	    /**
825	     * Returns the first {@code length} characters of the SHA-256 digest of {@code input}, rendered as
826	     * upper-case hexadecimal. Used to derive the {@code customerCode} hash segment and the household
827	     * identifier, both stable functions of their inputs.
828	     */
829	    private static String shaHexUpper(String input, int length) {
830	        try {
831	            byte[] digest = MessageDigest.getInstance("SHA-256")
832	                .digest(input.getBytes(StandardCharsets.UTF_8));
833	            StringBuilder hex = new StringBuilder(digest.length * 2);
834	            for (byte b : digest) {
835	                hex.append(String.format("%02x", b));
836	            }
837	            return hex.substring(0, length).toUpperCase(Locale.ROOT);
838	        } catch (NoSuchAlgorithmException ex) {
839	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
840	        }
841	    }
842	}
